      Promise.resolve().then(() => this.check());
    }

    async check() {
      while (true) {
        await new Promise(resolve => step_timeout(resolve, this.delayMs));
        if (this.cancelled) {
          return;
        }
        this.callback();
      }
    }

    cancel() {
      this.cancelled = true;
    }
  }

